def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
            yield b

F_sequence = []
for k in range(2, 26):
    F_k = 0
    # Calculate F_k iteratively
    a, b = 0, 1
    for _ in range(k - 1):
        a, b = b, a + b
    F_k = b
    F_sequence.append(F_k)

